<script setup>
import { computed,onMounted,ref } from 'vue';import { api } from '../api';import { useRouter } from 'vue-router';import { session } from '../session';import Chart from '../components/Chart.vue'
const router=useRouter(),data=ref(null),products=ref([]),shops=ref([]),error=ref(''),loading=ref(false),keyword=ref(''),shopId=ref(''),from=ref(''),to=ref(''),page=ref(1),total=ref(0)
const product=ref({product_code:'',name:'',category:'服装',base_price:'299.00'}),shop=ref({shop_code:'',platform:'淘宝（模拟）',name:'',platform_shop_id:''}),operator=computed(()=>session.user?.role==='operator')
async function load(){loading.value=true;error.value='';try{const query=new URLSearchParams();if(shopId.value)query.set('shop_id',shopId.value);if(from.value)query.set('date_from',from.value);if(to.value)query.set('date_to',to.value);const productQuery=new URLSearchParams({keyword:keyword.value,page:page.value});if(shopId.value)productQuery.set('shop_id',shopId.value);const [d,p]=await Promise.all([api.dashboard('?'+query),api.request('/products?'+productQuery)]);data.value=d;shops.value=d.shops;products.value=p.items;total.value=p.total}catch(e){error.value=e.message}finally{loading.value=false}}
async function create(type){loading.value=true;error.value='';try{const result=await api.request('/'+type,{method:'POST',body:type==='products'?product.value:shop.value});if(type==='products')await router.push(`/workbench/${result.id}`);else await load()}catch(e){error.value=e.message}finally{loading.value=false}}
const chart=computed(()=>({tooltip:{trigger:'axis'},legend:{},xAxis:{type:'category',data:data.value?.trend.map(x=>x.date)||[]},yAxis:{type:'value',name:'元'},series:[{name:'GMV',type:'line',data:data.value?.trend.map(x=>Number(x.totals.gmv))||[]},{name:'广告花费',type:'line',data:data.value?.trend.map(x=>Number(x.totals.ad_spend))||[]}]}))
onMounted(load)
</script>
<template><section class="page stack"><div class="page-heading"><div><div class="eyebrow">OPERATIONS OVERVIEW</div><h2>运营大盘</h2><p>多店铺运营概览 · 教学用途</p></div><RouterLink class="primary" to="/imports">批量导入</RouterLink></div><p v-if="error" class="error" role="alert">{{error}}</p><form class="form-grid" @submit.prevent="page=1;load()"><label>店铺范围<select v-model="shopId"><option value="">全部店铺</option><option v-for="s in shops" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>开始日期（默认近 7 天）<input type="date" v-model="from"></label><label>结束日期<input type="date" v-model="to"></label><label>商品名称／编码<input v-model="keyword" placeholder="检索商品"></label><button class="primary" :disabled="loading">查询</button></form><template v-if="data"><div class="metric-grid"><article><span>统一商品总数</span><strong>{{data.product_count}}</strong></article><article><span>范围内在售商品</span><strong>{{data.on_sale_product_count}}</strong></article><article><span>在售动销率</span><strong>{{data.sell_through_rate==null?'不可计算':(data.sell_through_rate*100).toFixed(1)+'%'}}</strong></article><article><span>期间 GMV</span><strong>¥{{data.totals.gmv}}</strong></article></div><section class="panel"><h3>经营走势（{{data.date_from}}—{{data.date_to}}）</h3><Chart :option="chart"/></section><div class="section-grid"><section class="panel"><h3>店铺概览</h3><div v-for="s in shops" :key="s.id" class="list-row"><b>{{s.name}} · {{s.product_count}} 款商品</b><span>{{s.platform}} · {{s.authorization_status}}</span></div><form v-if="operator" class="stack" @submit.prevent="create('shops')"><h4>快速创建店铺</h4><label v-for="(_v,key) in shop" :key="key">{{({shop_code:'店铺编码',platform:'平台（模拟授权）',name:'店铺名称',platform_shop_id:'平台店铺标识'})[key]}}<input v-model="shop[key]" required></label><button class="primary" :disabled="loading">创建店铺</button></form></section><section class="panel"><h3>商品档案</h3><button v-for="p in products" :key="p.id" class="list-row clickable" @click="router.push(`/workbench/${p.id}`)"><b>{{p.name}}</b><span>{{p.product_code}} · ¥{{p.base_price}}</span></button><p v-if="!products.length">暂无符合条件的商品。</p><div class="toolbar"><button class="ghost" :disabled="loading||page===1" @click="page--;load()">上一页</button><span>共 {{total}} 款</span><button class="ghost" :disabled="loading||page*50>=total" @click="page++;load()">下一页</button></div><form v-if="operator" class="stack" @submit.prevent="create('products')"><h4>快速录入商品</h4><label v-for="(_v,key) in product" :key="key">{{({product_code:'统一商品编码',name:'商品名称',category:'品类',base_price:'基准售价（元）'})[key]}}<input v-model="product[key]" required></label><button class="primary" :disabled="loading">建档并进入工作台</button></form></section></div><section class="panel"><h3>库存预警（{{data.inventory_alerts.length}} 项）</h3><div v-for="m in data.inventory_alerts" :key="m.id" class="list-row"><RouterLink :to="`/workbench/${m.product_id}`">{{m.platform_sku_id}}</RouterLink><span class="error">库存 {{m.stock_quantity}} ≤ 阈值 {{m.warning_threshold}} · 店铺 #{{m.shop_id}}</span></div><p v-if="!data.inventory_alerts.length">当前范围无库存预警。</p></section></template></section></template>
